McpInclusionMode = Literal["all_sessions", "opt_in"]
"""Per-integration policy for whether that integration's MCP server is added
to an agent session.

- ALL_SESSIONS: the MCP is added to every session (the historical behavior
  and the default, so this is a no-op for existing customers).
- OPT_IN: the MCP is added only to sessions whose agent names this
  integration in its `mcp_servers`. A config that does not opt in simply
  runs without the MCP — the same as if the integration were disconnected."""


