class ReviewedCommit(EllipsisModel):
    """One commit inside a run's reviewed range, snapshotted at mint time.

    Stored rather than re-derived: `watermark...head` is only resolvable against
    the PR's history as it was when the run was minted, and a force-push (or a
    merge) makes those SHAs unreachable — the range would then render as two
    orphan SHAs forever. The mint path already holds the PR's ordered commit
    list, so this costs no extra GitHub call.
    """

    author_avatar_url: Union[str, None] = None
    author_login: Union[str, None] = None
    authored_at: Union[str, None] = None
    message: str
    sha: str


class Review(EllipsisModel):
    """One code review: one pipeline iteration over one commit range of a pull
    request.

    `review_body`, `findings`, and `counters` are produced as each stage
    session finishes — while a review is running they are null/empty. Stream a
    stage's session to follow it live, then re-fetch the review.
    """

    budget_millicents: Union[int, None] = Field(
        default=None,
        description="The configured per-review budget in millicents — what one review may spend across every stage. Null when the pipeline sets no per-review budget, in which case spend is capped per stage session instead.",
    )
    completed_at: Union[str, None] = Field(
        default=None, description="When the review finished; null while it is running."
    )
    configuration: Union[ReviewConfiguration, None] = Field(
        default=None,
        description="The configuration that ran, frozen at creation. Omitted on list responses.",
    )
    cost_millicents: int = Field(
        default=0,
        description="Total spend across all stages, in millicents (1000 = $0.01).",
    )
    counters: Union[ReviewCounters, None] = Field(
        default=None,
        description="Parser and anchor reliability counters, summed across stages.",
    )
    created_at: Union[str, None] = Field(
        default=None, description="When the review was created."
    )
    description_error: Union[str, None] = Field(
        default=None, description="The description stage's error, when it failed."
    )
    description_outcome: Union[str, None] = Field(
        default=None,
        description="What the description stage did to the pull request body: updated, removed, skipped, unchanged, or error. Null when the pipeline runs no description agent.",
    )
    findings: list[ReviewFinding] = Field(
        default_factory=list,
        description="The review's findings, each carrying the pipeline's verdict. Omitted on list responses.",
    )
    id: str = Field(description="The review's unique identifier.")
    post: bool = Field(
        default=True,
        description="Whether the caller asked for this review to be posted to GitHub.",
    )
    post_error: Union[str, None] = Field(
        default=None, description="Why posting to GitHub failed, when it did."
    )
    posted_review_id: Union[int, None] = Field(
        default=None,
        description="The GitHub review id this review was posted as, if any.",
    )
    pull_request: ReviewPullRequest = Field(
        description="The pull request the review ran on."
    )
    repository: ReviewRepository = Field(
        description="The repository the review ran on."
    )
    requested_by: Union[ReviewRequester, None] = Field(
        default=None,
        description="Who requested the review; null for automatic reviews triggered by a push.",
    )
    review_body: Union[str, None] = Field(
        default=None,
        description="The review's summary body; null while the review is running.",
    )
    reviewed_commits: list[ReviewedCommit] = Field(
        default_factory=list,
        description="The commits the range covered, oldest first, snapshotted when the review was created. Empty for older reviews, or when the pull request's history was rewritten first.",
    )
    scope: ResolvedReviewScope = Field(
        description="The commit range the review covered."
    )
    skip_reason: Union[str, None] = Field(
        default=None, description="Why the review was skipped, when it was."
    )
    stages: list[ReviewStage] = Field(
        default_factory=list, description="The pipeline stages that make up the review."
    )
    status: str = Field(
        description='The review\'s status, or the synthetic "skipped" for an incremental review with nothing new to look at.'
    )
    trigger: str = Field(description="What triggered the review.")


