class Session(EllipsisModel):
    """An agent session: one conversation with an agent, from trigger to
    terminal state. Returned by `GET /v1/sessions/{id}` and carried by the
    session stream's `session`/`snapshot` frames — REST and stream never
    disagree about what a session looks like.
    """

    agent: Union[SessionAgent, None] = Field(
        description="The agent the session was started from, or null for a raw session started with POST /v1/sessions."
    )
    attribution: SessionAttribution = Field(
        description="The principal this session is attributed to."
    )
    budget: float = Field(
        description="The spend budget enforced for this session, in US dollars, after resolving defaults and ceilings."
    )
    claude_code: Union[ClaudeConfig_Output, None] = Field(
        description="Claude Code input and native options. Set exactly one of claude_code or codex."
    )
    codex: Union[CodexConfig_Output, None] = Field(
        description="Codex input and native options. Set exactly one of claude_code or codex."
    )
    cost: SessionCost = Field(
        description="What the session cost, in millicents, broken down by leg and carrying its own total."
    )
    environment: SessionEnvironment = Field(
        description="The full environment configuration frozen when the session was created, with the saved environment's id and how it was chosen."
    )
    event: Union[
        Union[
            GithubPullRequestEvent,
            GithubIssueEvent,
            GithubPushEvent,
            LinearIssueEvent,
            SlackMessageEvent,
            SlackChannelCreatedEvent,
            SentryAlertEvent,
        ],
        None,
    ] = Field(
        description="The typed external event that started the session; null for direct and scheduled starts."
    )
    git: Union[SessionGit, None] = Field(
        description="What the session did to git, one entry per repository in its workspace: the commit and branch it sits on, per-file line counts for its uncommitted changes, and the pull requests it opened. Null if nothing was ever captured."
    )
    handler: Union[SessionHandler, None] = Field(
        description="The saved handler and its effective display name when this session started, frozen at creation. Null for built-in responders, legacy sessions, and sessions started without a handler."
    )
    id: str = Field(description="Unique identifier of the session.")
    lifecycle: SessionLifecycle = Field(
        description="The session's activity, conversation state, messaging policy, outcomes, and timestamps."
    )
    metadata: dict[str, str] = Field(
        description="Caller-supplied metadata key-value pairs."
    )
    output: Union[OutputConfig, None] = Field(
        description="The structured-output exit contract for this session."
    )
    parent: Union[SessionParent, None] = Field(
        description="The predecessor session this session continues; null when there is none."
    )
    permissions: PermissionsConfig_Output = Field(
        description="What the session may touch, per minted credential."
    )
    skills: list[SkillRef_Output] = Field(
        description="Skills installed for this session."
    )
    source: SessionSource = Field(
        description="Where the session came from (e.g. react, web, api, cli, mention, cron)."
    )
    summary: Union[SessionSummary, None] = Field(
        description="The latest live summary of the session's progress while it runs, and when it was generated."
    )
    tokens: SessionTokens = Field(
        description="The tokens the session spent and the model they went to. `total` includes the prompt-cache lanes."
    )


