class SessionGitPatchFile(EllipsisModel):
    """One file's patch, split out of `git diff HEAD` at capture time.

    Stored per file rather than as one blob because that is how a viewer reads
    it: a row per changed file, opened one at a time. Counts and status are NOT
    repeated here — they live on the matching SessionGitFile in
    `sessions.output_git`, which rides on every session read, so a surface
    lists the changed files (and their +/−) before it fetches a single hunk. The
    join key is (full_name, path).

    `patch` is the unified-diff section for this file, `diff --git` header
    included, exactly as git emitted it.
    """

    full_name: str
    patch: str
    path: str


