SubscriptionProvider = Literal["claude", "codex"]
"""Named for the harness the token drives, not the vendor behind it: a
developer connects "my Claude subscription", and the path segment they
type is `claude`."""


class SubscriptionToken(EllipsisModel):
    """One provider's subscription token, as the API publishes it. The token
    itself is never here — the store is write-only.
    """

    configured: bool = Field(
        default=False,
        description="Whether a token is saved for this provider. False means nothing is stored and the other fields are empty.",
    )
    enabled: bool = Field(
        default=False,
        description="Whether the token is routing. Only a successful verify sets it; a failed verify clears it, so a revoked token stops routing.",
    )
    provider: SubscriptionProvider = Field(description="The harness the token drives.")
    token_last4: Union[str, None] = Field(
        default=None,
        description="The last four characters of the stored token, for display. The token itself is never returned.",
    )


class SubscriptionTokensListResponse(EllipsisModel):
    """Every provider, whether or not a token is saved for it."""

    tokens: list[SubscriptionToken] = Field(
        description="One entry per supported provider, in a stable order."
    )


class SubscriptionUsageWindow(EllipsisModel):
    """One rate-limit window of the developer's plan."""

    resets_at: Union[datetime, None] = Field(
        default=None,
        description="When the window rolls over and the allowance is restored. Null when the provider did not report it.",
    )
    surpassed_threshold: Union[bool, None] = Field(
        default=None,
        description="Whether the provider marks this window as nearly spent. Null when it did not report it, which is not the same as false.",
    )
    utilization: float = Field(description="Fraction of the window consumed, 0 to 1.")


class SubscriptionUsage(EllipsisModel):
    """The plan's last-observed rate-limit state.

    Display-only. Nothing routes, retries, or falls back on it, and it is only
    as fresh as the developer's last call through Ellipsis (`observed_at`) —
    Claude Code run locally on the same plan moves the real windows without us
    seeing them.
    """

    five_hour: Union[SubscriptionUsageWindow, None] = Field(
        default=None, description="The rolling five-hour session window."
    )
    observed_at: datetime = Field(
        description="When the response carrying these windows was received."
    )
    overage: Union[SubscriptionOverage, None] = Field(
        default=None,
        description="The paid overage balance the plan draws from once its included windows are exhausted. Null for a plan with no overage.",
    )
    representative_claim: Union[str, None] = Field(
        default=None,
        description="Which window the provider considers binding right now, e.g. `five_hour`. Null when not reported.",
    )
    seven_day: Union[SubscriptionUsageWindow, None] = Field(
        default=None, description="The weekly cap."
    )
    status: str = Field(
        description="The provider's own verdict on the plan right now: `allowed`, `allowed_warning`, or `rejected`."
    )


